// Topographic Explorer Design - Campground Data
// All 49 campgrounds sorted by drive time from Redmond, WA

export interface Activity {
  name: string;
  ageRange: string;
  distance: string;
  details: string;
  mapUrl?: string;
  googleRating?: string;
}

export interface AreaRating {
  area: string;
  overall: number;
  scenery: number;
  kidFriendly: number;
  tcCompat: number;
  hookups: string;
  recommendation: string;
  areaSummary?: string;
  entranceUrl?: string; // Google Maps direction URL to this specific area's entrance
}

export interface VacancyInfo {
  area: string;
  whyVacant: string;
  whyHard: string;
}

export interface BookingWindow {
  area: string;
  advanceDays: number;
  advanceLabel: string;
  notes: string;
}

export type CampgroundTier = "顶级热门" | "明显热门" | "区域家庭优选" | "商业度假型" | "2026受限" | "不适配";

export interface ClosureInfo {
  reason: string;
  closedSince: string;
  expectedReopen: string;
  source: string;
  lastChecked: string;
}

export interface Campground {
  id: number;
  name: string;
  nameCn: string;
  tagline: string;
  description?: string;
  tier?: CampgroundTier;
  closureInfo?: ClosureInfo;
  popularityLevel?: string;
  reviewCount?: string;
  driveTime: number; // in minutes
  driveTimeLabel: string;
  sceneryRating: number;
  kidRating: number;
  tcRating: number;
  state: "WA" | "OR" | "BC";
  region: string;
  type: "state" | "national" | "county" | "private" | "usfs" | "provincial";
  features: string[];
  warning?: string;
  bookingUrl: string;
  bookingSystem: string;
  season: string;
  activities: Activity[];
  areas: AreaRating[];
  vacancyAnalysis: VacancyInfo[];
  bookingWindows: BookingWindow[];
  recommendedSites: string;
  avoid: string;
  tcNotes: string;
  image: string;
  lat?: number;
  lng?: number;
  googleMapsUrl?: string; // Google Maps URL for the campground
  lastUpdated?: string; // ISO date string e.g. "2026-07-12"
}

