    description: "Trillium Lake 露营地位于波特兰东南约40英里处，坐落在胡德山国家森林，临近 Trillium Lake，海拔约3,600 英尺 (Source: https://www.fs.usda.gov/r06/mthood/recreation/trillium-lake-campground)。该营地提供数十个适合帐篷和房车的单人及双人营位，坐落在一片荫凉的混合针叶林中，营位之间保持良好私密性 (Source: https://www.recreation.gov/camping/campgrounds/232831)。它以观赏胡德山的壮丽景色和丰富的休闲活动而闻名，包括在禁止机动船只的湖上划船、游泳和垂钓 (Source: https://www.fs.usda.gov/r06/mthood/recreation/trillium-lake-campground)。 【2026-11-21 更新】2026-11-04 TheDyrt 新评价（Kaidan S.）：湖边付费位之外，森林路深处有免费分散露营，可倒车进 truck、有石火圈、非常僻静。2026 年 8 月 TripAdvisor 评价（Basanthi P.）：湖景好。 小红书实住帖（孤松山语，2026-09-17）：Mt. Hood 以东约 20 公里山火，空气质量“对敏感人群不健康”，有人最后一刻取消预约；先到先得位一般中午即满；晚上 7 点多到仍有 ranger 安排近水好位；湖原名 Mud Lake、人工湖，每年三次投放 10–12 英寸鳟鱼。https://www.xiaohongshu.com/explore/6aa7252a0000000011031e80 【2026-11-22 更新】TheDyrt 新增 1 条可定位评价（作者/发布日期未显示，到访 9 月，Site 4）：“$30 per night, you gotta check out by noon and they wont let you in till noon. Very nice people and helpful though. Lake views all around and lots of picnic tables everywhere.”现价 $30/晚。https://thedyrt.com/camping/oregon/oregon-trillium-lake-campground",
